import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

depthwise_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels,
    int input_height, int input_width,
    int kernel_size, int stride, int padding,
    int output_height, int output_width,
    bool has_bias
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * in_channels * output_height * output_width;
    if (index >= total_elements) return;

    int n = index / (in_channels * output_height * output_width);
    int remainder = index % (in_channels * output_height * output_width);
    int c = remainder / (output_height * output_width);
    remainder = remainder % (output_height * output_width);
    int h_out = remainder / output_width;
    int w_out = remainder % output_width;

    float sum = 0.0f;

    int h_start = h_out * stride - padding;
    int w_start = w_out * stride - padding;

    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            int h_in = h_start + kh;
            int w_in = w_start + kw;

            if (h_in >= 0 && h_in < input_height && w_in >= 0 && w_in < input_width) {
                int input_idx = n * (in_channels * input_height * input_width) + 
                               c * (input_height * input_width) + 
                               h_in * input_width + w_in;
                int weight_idx = c * (kernel_size * kernel_size) + 
                               kh * kernel_size + kw;
                sum += input[input_idx] * weight[weight_idx];
            }
        }
    }

    if (has_bias) {
        sum += bias[c];
    }

    output[index] = sum;
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input, torch::Tensor weight, torch::optional<torch::Tensor> bias,
    int stride, int padding
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_height = input.size(2);
    int input_width = input.size(3);
    int kernel_size = weight.size(2);

    int output_height = (input_height + 2 * padding - kernel_size) / stride + 1;
    int output_width = (input_width + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, in_channels, output_height, output_width}, input.options());

    int total_elements = batch_size * in_channels * output_height * output_width;
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    depthwise_conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.has_value() ? bias->data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        input_height,
        input_width,
        kernel_size,
        stride,
        padding,
        output_height,
        output_width,
        bias.has_value()
    );

    return output;
}
"""

depthwise_conv2d_cpp_source = "torch::Tensor depthwise_conv2d_cuda(torch::Tensor input, torch::Tensor weight, torch::optional<torch::Tensor> bias, int stride, int padding);"

depthwise_conv2d = load_inline(
    name="depthwise_conv2d",
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=["depthwise_conv2d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding

        self.weight = nn.Parameter(torch.Tensor(in_channels, 1, kernel_size, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(in_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=0, mode='fan_in', nonlinearity='conv2d')
        if self.bias is not None:
            nn.init.zeros_(self.bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return depthwise_conv2d.depthwise_conv2d_cuda(
            x, 
            self.weight, 
            self.bias if self.bias is not None else torch::optional<torch::Tensor>(),
            self.stride,
            self.padding
        )
